'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const number = input[0];
const m = Number(input[1]);
const digitFor = new Array(26);

const groups = [
  ['abc', '2'], ['def', '3'], ['ghi', '4'], ['jkl', '5'],
  ['mno', '6'], ['pqrs', '7'], ['tuv', '8'], ['wxyz', '9']
];

for (const [letters, digit] of groups) {
  for (const letter of letters) {
    digitFor[letter.charCodeAt(0) - 97] = digit;
  }
}

let answer = 0;

for (let i = 0; i < m; i++) {
  const word = input[i + 2];
  if (word.length !== number.length) continue;

  let matches = true;
  for (let j = 0; j < number.length; j++) {
    if (digitFor[word.charCodeAt(j) - 97] !== number[j]) {
      matches = false;
      break;
    }
  }

  if (matches) answer++;
}

console.log(answer);
